__modules["features/player"] = function()
local Players = game:GetService("Players")
local RunService = game:GetService("RunService")
local UserInputService = game:GetService("UserInputService")

local Config = __require("config")
local Util = __require("util")

local Player = {}

local state = {
	flying = false,
	flyBody = nil,
	flyConn = nil,
	noclipConn = nil,
	jumpConn = nil,
	bhopConn = nil,
	hoverBody = nil,
	hoverConn = nil,
	fallConn = nil,
	touched = {},
}

local function destroyFlyBody()
	if state.flyBody then
		state.flyBody:Destroy()
		state.flyBody = nil
	end
end

local function startFlyBody()
	destroyFlyBody()
	local root = Util.getRoot()
	if not root then
		return false
	end

	local body = Instance.new("BodyVelocity")
	body.Name = "DoloHook_Fly"
	body.MaxForce = Vector3.new(1e5, 1e5, 1e5)
	body.Velocity = Vector3.zero
	body.Parent = root
	state.flyBody = body
	return true
end

local function readMoveVector()
	local camera = workspace.CurrentCamera
	if not camera then
		return Vector3.zero
	end

	local direction = Vector3.zero
	if UserInputService:IsKeyDown(Enum.KeyCode.W) then
		direction += camera.CFrame.LookVector
	end
	if UserInputService:IsKeyDown(Enum.KeyCode.S) then
		direction -= camera.CFrame.LookVector
	end
	if UserInputService:IsKeyDown(Enum.KeyCode.D) then
		direction += camera.CFrame.RightVector
	end
	if UserInputService:IsKeyDown(Enum.KeyCode.A) then
		direction -= camera.CFrame.RightVector
	end
	if UserInputService:IsKeyDown(Enum.KeyCode.Space) then
		direction += Vector3.yAxis
	end
	if UserInputService:IsKeyDown(Enum.KeyCode.LeftControl) then
		direction -= Vector3.yAxis
	end

	if direction.Magnitude > 0 then
		direction = direction.Unit
	end
	return direction
end

function Player.setWalkSpeed(value)
	local humanoid = Util.getHumanoid()
	if not humanoid then
		return false, "no character"
	end
	Config.set("WalkSpeed", value)
	humanoid.WalkSpeed = value
	return true
end

function Player.setJumpPower(value)
	local humanoid = Util.getHumanoid()
	if not humanoid then
		return false, "no character"
	end
	Config.set("JumpPower", value)
	humanoid.UseJumpPower = true
	humanoid.JumpPower = value
	return true
end

function Player.setNoClip(enabled)
	if enabled then
		if state.noclipConn then
			return true
		end
		state.noclipConn = RunService.Stepped:Connect(function()
			for _, part in ipairs(Util.getParts(Util.getCharacter())) do
				if part.CanCollide then
					state.touched[part] = true
					part.CanCollide = false
				end
			end
		end)
		return true
	end

	if state.noclipConn then
		state.noclipConn:Disconnect()
		state.noclipConn = nil
	end
	for part in pairs(state.touched) do
		if part.Parent then
			part.CanCollide = true
		end
	end
	table.clear(state.touched)
	return true
end

function Player.setFly(enabled)
	state.flying = enabled

	local humanoid = Util.getHumanoid()

	if not enabled then
		destroyFlyBody()
		if state.flyConn then
			state.flyConn:Disconnect()
			state.flyConn = nil
		end
		if humanoid then
			humanoid.PlatformStand = false
		end
		return true
	end

	if not startFlyBody() then
		state.flying = false
		return false, "no character"
	end
	if humanoid then
		humanoid.PlatformStand = true
	end

	if not state.flyConn then
		state.flyConn = RunService.RenderStepped:Connect(function()
			if not state.flying then
				return
			end
			if not state.flyBody or not state.flyBody.Parent then
				if not startFlyBody() then
					return
				end
			end
			state.flyBody.Velocity = readMoveVector() * Config.get("FlySpeed")
		end)
	end
	return true
end

function Player.setInfiniteJump(enabled)
	if not enabled then
		if state.jumpConn then
			state.jumpConn:Disconnect()
			state.jumpConn = nil
		end
		return true
	end

	if state.jumpConn then
		return true
	end
	state.jumpConn = UserInputService.JumpRequest:Connect(function()
		local humanoid = Util.getHumanoid()
		if humanoid and humanoid.Health > 0 then
			humanoid:ChangeState(Enum.HumanoidStateType.Jumping)
		end
	end)
	return true
end

function Player.resetCharacter()
	local humanoid = Util.getHumanoid()
	if not humanoid then
		return false, "no character"
	end
	humanoid.Health = 0
	return true
end

function Player.setNoFallDamage(enabled)
	Config.set("NoFallDamage", enabled)

	if not enabled then
		if state.fallConn then
			state.fallConn:Disconnect()
			state.fallConn = nil
		end
		local humanoid = Util.getHumanoid()
		if humanoid then
			pcall(function()
				humanoid:SetStateEnabled(Enum.HumanoidStateType.FallingDown, true)
			end)
		end
		return true
	end

	if state.fallConn then
		return true
	end
	state.fallConn = RunService.Heartbeat:Connect(function()
		local humanoid = Util.getHumanoid()
		if humanoid then
			pcall(function()
				humanoid:SetStateEnabled(Enum.HumanoidStateType.FallingDown, false)
			end)
		end
	end)
	return true
end

function Player.setFreeze(enabled)
	Config.set("Freeze", enabled)

	local root = Util.getRoot()
	if not root then
		return false, "no character"
	end
	root.Anchored = enabled
	return true
end

function Player.bind()
	local localPlayer = Players.LocalPlayer
	if not localPlayer then
		return
	end

	localPlayer.CharacterAdded:Connect(function(character)
		task.wait(0.4)
		if character ~= Util.getCharacter() then
			return
		end

		local humanoid = character:FindFirstChildOfClass("Humanoid")
		if humanoid then
			humanoid.WalkSpeed = Config.get("WalkSpeed")
			humanoid.UseJumpPower = true
			humanoid.JumpPower = Config.get("JumpPower")
		end

		if Config.get("Fly") then
			Player.setFly(true)
		end
		if Config.get("NoClip") then
			Player.setNoClip(true)
		end
	end)
end

function Player.setBhop(enabled)
	Config.set("Bhop", enabled)

	if not enabled then
		if state.bhopConn then
			state.bhopConn:Disconnect()
			state.bhopConn = nil
		end
		return true
	end

	if state.bhopConn then
		return true
	end
	state.bhopConn = RunService.Heartbeat:Connect(function()
		local humanoid = Util.getHumanoid()
		if not humanoid or humanoid.Health <= 0 then
			return
		end
		local current = humanoid:GetState()
		if current == Enum.HumanoidStateType.Landed or current == Enum.HumanoidStateType.Running then
			humanoid:ChangeState(Enum.HumanoidStateType.Jumping)
		end
	end)
	return true
end

local function attachHover()
	local root = Util.getRoot()
	if not root then
		return false
	end
	if state.hoverBody then
		state.hoverBody:Destroy()
	end

	local body = Instance.new("BodyVelocity")
	body.Name = "DoloHook_Hover"
	body.MaxForce = Vector3.new(1e5, 1e5, 1e5)
	body.Velocity = Vector3.zero
	body.Parent = root
	state.hoverBody = body
	return true
end

function Player.setHover(enabled)
	Config.set("Hover", enabled)

	if not enabled then
		if state.hoverConn then
			state.hoverConn:Disconnect()
			state.hoverConn = nil
		end
		if state.hoverBody then
			state.hoverBody:Destroy()
			state.hoverBody = nil
		end
		return true
	end

	if not attachHover() then
		return false, "no character"
	end

	if not state.hoverConn then
		state.hoverConn = RunService.RenderStepped:Connect(function()
			if not state.hoverBody or not state.hoverBody.Parent then
				if not attachHover() then
					return
				end
			end
			state.hoverBody.Velocity = Vector3.zero
		end)
	end
	return true
end

function Player.destroy()
	Player.setFly(false)
	Player.setNoClip(false)
	Player.setInfiniteJump(false)
	Player.setBhop(false)
	Player.setHover(false)
	Player.setNoFallDamage(false)
	pcall(function()
		Player.setFreeze(false)
	end)
end

return Player
end
__modules["features/esp"] = function()
local CoreGui = game:GetService("CoreGui")
local Players = game:GetService("Players")
local RunService = game:GetService("RunService")

local Util = __require("util")

local ESP = {}

local container
local tracked = {}
local connection
local fill = Color3.fromRGB(120, 180, 255)

local function getContainer()
	if container and container.Parent then
		return container
	end

	local folder = Instance.new("Folder")
	folder.Name = "DoloHook_ESP"

	local ok = pcall(function()
		folder.Parent = CoreGui
	end)
	if not ok or not folder.Parent then
		local camera = workspace.CurrentCamera
		if camera then
			folder.Parent = camera
		end
	end

	container = folder
	return container
end

local function isTarget(player)
	return player ~= Players.LocalPlayer and player.Character ~= nil
end

local function attach(player)
	if not isTarget(player) then
		return
	end

	local character = player.Character
	if not character or not character:FindFirstChildOfClass("Humanoid") then
		return
	end

	local highlight = tracked[player]
	if highlight and highlight.Parent then
		highlight.Adornee = character
		return
	end

	highlight = Instance.new("Highlight")
	highlight.Name = "DoloHook_ESP_" .. player.Name
	highlight.Adornee = character
	highlight.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
	highlight.FillColor = fill
	highlight.FillTransparency = 0.55
	highlight.OutlineColor = fill
	highlight.OutlineTransparency = 0
	highlight.Parent = getContainer()

	tracked[player] = highlight
end

local function detach(player)
	local highlight = tracked[player]
	if highlight then
		highlight:Destroy()
		tracked[player] = nil
	end
end

local function clearAll()
	for player in pairs(tracked) do
		detach(player)
	end
	table.clear(tracked)
end

local function sweep()
	for _, player in ipairs(Players:GetPlayers()) do
		attach(player)
	end
end

function ESP.setEnabled(enabled)
	if not enabled then
		if connection then
			connection:Disconnect()
			connection = nil
		end
		clearAll()
		return true
	end

	sweep()

	if not connection then
		connection = RunService.Heartbeat:Connect(function()
			sweep()
			for player, highlight in pairs(tracked) do
				if not player.Parent or not player.Character then
					detach(player)
				elseif highlight.Adornee ~= player.Character then
					highlight.Adornee = player.Character
				end
			end
		end)
	end
	return true
end

function ESP.setColor(color)
	fill = color
	for _, highlight in pairs(tracked) do
		if highlight.Parent then
			highlight.FillColor = color
			highlight.OutlineColor = color
		end
	end
	return true
end

function ESP.bind()
	Players.PlayerAdded:Connect(function(player)
		if connection then
			player.CharacterAdded:Connect(function()
				if connection then
					task.wait(0.3)
					attach(player)
				end
			end)
		end
	end)
	Players.PlayerRemoving:Connect(detach)
end

function ESP.destroy()
	ESP.setEnabled(false)
	if container then
		container:Destroy()
		container = nil
	end
end

return ESP
end
__modules["features/teleport"] = function()
local Players = game:GetService("Players")
local UserInputService = game:GetService("UserInputService")

local Util = __require("util")

local Teleport = {}

local waypoints = {}

function Teleport.saveWaypoint(name)
	name = tostring(name or ""):gsub("^%s+", ""):gsub("%s+$", "")
	if name == "" then
		return false, "empty name"
	end

	local camera = workspace.CurrentCamera
	if not camera then
		return false, "no camera"
	end

	waypoints[name] = camera.CFrame * CFrame.new(0, 0, -6)
	return true, name
end

function Teleport.deleteWaypoint(name)
	if not waypoints[name] then
		return false, "unknown waypoint"
	end
	waypoints[name] = nil
	return true
end

function Teleport.waypointNames()
	local names = {}
	for name in pairs(waypoints) do
		table.insert(names, name)
	end
	table.sort(names)
	return names
end

function Teleport.toWaypoint(name)
	local target = waypoints[name]
	if not target then
		return false, "unknown waypoint"
	end

	local character = Util.getCharacter()
	if not character then
		return false, "no character"
	end
	character:PivotTo(target)
	return true
end

function Teleport.playerNames()
	local names = {}
	for _, player in ipairs(Players:GetPlayers()) do
		if player ~= Players.LocalPlayer then
			table.insert(names, player.Name)
		end
	end
	table.sort(names)
	return names
end

function Teleport.toPlayer(name)
	local target = Players:FindFirstChild(name)
	if not target then
		return false, "player left"
	end

	local targetRoot = target.Character and target.Character:FindFirstChild("HumanoidRootPart")
	if not targetRoot then
		return false, "target has no character"
	end

	local character = Util.getCharacter()
	if not character then
		return false, "no character"
	end
	character:PivotTo(CFrame.new(targetRoot.Position + Vector3.new(0, 3, 0)))
	return true
end

function Teleport.toPosition(vector)
	if typeof(vector) ~= "Vector3" then
		return false, "not a Vector3"
	end
	local character = Util.getCharacter()
	if not character then
		return false, "no character"
	end
	character:PivotTo(CFrame.new(vector))
	return true
end

function Teleport.toCursor()
	local camera = workspace.CurrentCamera
	if not camera then
		return false, "no camera"
	end

	local mouse = UserInputService:GetMouseLocation()
	local ray = camera:ViewportPointToRay(mouse.X, mouse.Y)
	local params = RaycastParams.new()
	params.FilterType = Enum.RaycastFilterType.Exclude
	params.FilterDescendantsInstances = { Util.getCharacter() }

	local result = workspace:Raycast(ray.Origin, ray.Direction * 1000, params)
	if not result then
		return false, "nothing under the cursor"
	end
	return Teleport.toPosition(result.Position + Vector3.new(0, 3, 0))
end

function Teleport.spectate(name)
	local player = Players:FindFirstChild(name)
	if not player then
		return false, "player left"
	end
	local humanoid = player.Character and player.Character:FindFirstChildOfClass("Humanoid")
	if not humanoid then
		return false, "target has no character"
	end
	local camera = workspace.CurrentCamera
	if not camera then
		return false, "no camera"
	end
	camera.CameraSubject = humanoid
	return true
end

function Teleport.unspectate()
	local player = Players.LocalPlayer
	local humanoid = player and player.Character and player.Character:FindFirstChildOfClass("Humanoid")
	if humanoid then
		workspace.CurrentCamera.CameraSubject = humanoid
		return true
	end
	return false, "no character"
end

return Teleport
end
