local Lighting = game:GetService("Lighting")
local Players = game:GetService("Players")
local TeleportService = game:GetService("TeleportService")
local VirtualUser = game:GetService("VirtualUser")

local Misc = {}

local originals
local idleConn
local fogOriginals

function Misc.setFullbright(enabled)
	if enabled then
		if originals then
			return true
		end
		originals = {
			Ambient = Lighting.Ambient,
			OutdoorAmbient = Lighting.OutdoorAmbient,
			Brightness = Lighting.Brightness,
			ClockTime = Lighting.ClockTime,
			FogEnd = Lighting.FogEnd,
			GlobalShadows = Lighting.GlobalShadows,
		}
		Lighting.Ambient = Color3.fromRGB(200, 200, 200)
		Lighting.OutdoorAmbient = Color3.fromRGB(200, 200, 200)
		Lighting.Brightness = 3
		Lighting.ClockTime = 14
		Lighting.FogEnd = 1e6
		Lighting.GlobalShadows = false
		return true
	end

	if not originals then
		return true
	end
	for key, value in pairs(originals) do
		Lighting[key] = value
	end
	originals = nil
	return true
end

function Misc.setAntiAFK(enabled)
	if not enabled then
		if idleConn then
			idleConn:Disconnect()
			idleConn = nil
		end
		return true
	end

	if idleConn then
		return true
	end
	idleConn = Players.LocalPlayer.Idled:Connect(function()
		VirtualUser:CaptureController()
		VirtualUser:ClickButton2(Vector2.zero)
	end)
	return true
end

function Misc.rejoin()
	TeleportService:Teleport(game.PlaceId, Players.LocalPlayer)
	return true
end

function Misc.serverInfo()
	local info = {
		place = tostring(game.PlaceId),
		job = tostring(game.JobId),
		players = tostring(#Players:GetPlayers()),
	}
	return info
end

function Misc.copyJobId()
	local ok = pcall(function()
		setclipboard(tostring(game.JobId))
	end)
	return ok
end

function Misc.setNoFog(enabled)
	if enabled then
		if fogOriginals then
			return true
		end
		fogOriginals = { FogEnd = Lighting.FogEnd, FogStart = Lighting.FogStart }
		Lighting.FogEnd = 100000
		Lighting.FogStart = 100000
		return true
	end
	if fogOriginals then
		Lighting.FogEnd = fogOriginals.FogEnd
		Lighting.FogStart = fogOriginals.FogStart
		fogOriginals = nil
	end
	return true
end

function Misc.setCameraFOV(value)
	local camera = workspace.CurrentCamera
	if not camera then
		return false, "no camera"
	end
	camera.FieldOfView = value
	return true
end

function Misc.destroy()
	Misc.setFullbright(false)
	Misc.setNoFog(false)
	Misc.setAntiAFK(false)
end

return Misc
end
__modules["features/draw"] = function()
local Draw = {}

local library
do
	local ok, result = pcall(function()
		return Drawing
	end)
	if ok and type(result) == "table" and type(result.new) == "function" then
		library = result
	end
end

function Draw.available()
	return library ~= nil
end

local function make(kind, properties)
	if not library then
		return nil
	end

	local ok, object = pcall(function()
		return library.new(kind)
	end)
	if not ok or not object then
		return nil
	end

	for key, value in pairs(properties or {}) do
		pcall(function()
			object[key] = value
		end)
	end
	return object
end

local function set(object, properties)
	if not object then
		return
	end
	for key, value in pairs(properties) do
		pcall(function()
			object[key] = value
		end)
	end
end

local function remove(object)
	if not object then
		return
	end
	pcall(function()
		object:Remove()
	end)
end

Draw.set = set
Draw.remove = remove

function Draw.line(properties)
	return make("Line", properties)
end

function Draw.text(properties)
	return make("Text", properties)
end

function Draw.square(properties)
	return make("Square", properties)
end

function Draw.circle(properties)
	return make("Circle", properties)
end

function Draw.quad(properties)
	return make("Quad", properties)
end

return Draw
end
__modules["features/targeting"] = function()
local Players = game:GetService("Players")
local Workspace = game:GetService("Workspace")

local Targeting = {}

local RAY_PARAMS = RaycastParams.new()
RAY_PARAMS.FilterType = Enum.RaycastFilterType.Exclude

local function localPlayer()
	return Players.LocalPlayer
end

local function aliveCharacter(player)
	local character = player and player.Character
	if not character then
		return nil
	end
	local humanoid = character:FindFirstChildOfClass("Humanoid")
	if not humanoid or humanoid.Health <= 0 then
		return nil
	end
	return character, humanoid
end

function Targeting.isAlly(player)
	local me = localPlayer()
	if not me or not me.Team then
		return false
	end
	return player.Team == me.Team
end

function Targeting.candidates(options)
	options = options or {}
	local list = {}
	local me = localPlayer()
	if not me then
		return list
	end

	local camera = Workspace.CurrentCamera
	if not camera then
		return list
	end

	for _, player in ipairs(Players:GetPlayers()) do
		if player ~= me then
			local character, humanoid = aliveCharacter(player)
			if character and (not options.teamCheck or not Targeting.isAlly(player)) then
				local root = character:FindFirstChild("HumanoidRootPart")
				if root then
					local distance = (root.Position - camera.CFrame.Position).Magnitude
					if not options.maxDistance or distance <= options.maxDistance then
						list[#list + 1] = {
							player = player,
							character = character,
							humanoid = humanoid,
							root = root,
							distance = distance,
						}
					end
				end
			end
		end
	end
	return list
end

function Targeting.part(entry, name)
	local character = entry.character
	if name == "Head" then
		return character:FindFirstChild("Head")
	end
	if name == "Torso" then
		return character:FindFirstChild("UpperTorso") or character:FindFirstChild("Torso")
	end
	return entry.root
end

function Targeting.project(position)
	local camera = Workspace.CurrentCamera
	if not camera then
		return nil, false, 0
	end
	local screen, onScreen = camera:WorldToViewportPoint(position)
	if screen.Z <= 0 then
		onScreen = false
	end
	return Vector2.new(screen.X, screen.Y), onScreen, screen.Z
end

function Targeting.viewport()
	local camera = Workspace.CurrentCamera
	if camera then
		return camera.ViewportSize
	end
	return Vector2.new(1920, 1080)
end

function Targeting.visible(entry)
	local camera = Workspace.CurrentCamera
	if not camera then
		return false
	end
	local origin = camera.CFrame.Position
	local targetPosition = entry.root.Position

	RAY_PARAMS.FilterDescendantsInstances = { localPlayer().Character, entry.character }

	local result = Workspace:Raycast(origin, targetPosition - origin, RAY_PARAMS)
	return result == nil
end

function Targeting.closestToScreen(options)
	options = options or {}
	local viewport = Targeting.viewport()
	local center = viewport * 0.5
	local fov = options.fov or 0
	local priority = options.priority or "Crosshair"

	local best, bestScore
	for _, entry in ipairs(Targeting.candidates(options)) do
		local part = Targeting.part(entry, options.part or "Head")
		if part then
			local screen, onScreen = Targeting.project(part.Position)
			if screen and onScreen then
				local distance = (screen - center).Magnitude
				if fov <= 0 or distance <= fov then
					local score = distance
					if priority == "Distance" then
						score = entry.distance
					elseif priority == "Health" then
						score = entry.humanoid.Health
					end
					if not bestScore or score < bestScore then
						best, bestScore = entry, score
					end
				end
			end
		end
	end
	return best
end

return Targeting
end
__modules["features/visuals"] = function()
local Players = game:GetService("Players")
local RunService = game:GetService("RunService")
local Workspace = game:GetService("Workspace")

local Config = __require("config")
local Draw = __require("features/draw")
local Targeting = __require("features/targeting")

local Visuals = {}

local entries = {}
local connection
local color = Color3.fromRGB(120, 170, 255)
local fovCircle
local enabled = false

local SKELETON = {
	{ "Head", "UpperTorso" },
	{ "UpperTorso", "LowerTorso" },
	{ "UpperTorso", "LeftUpperArm" },
	{ "LeftUpperArm", "LeftLowerArm" },
	{ "LeftLowerArm", "LeftHand" },
	{ "UpperTorso", "RightUpperArm" },
	{ "RightUpperArm", "RightLowerArm" },
	{ "RightLowerArm", "RightHand" },
	{ "LowerTorso", "LeftUpperLeg" },
	{ "LeftUpperLeg", "LeftLowerLeg" },
	{ "LeftLowerLeg", "LeftFoot" },
	{ "LowerTorso", "RightUpperLeg" },
	{ "RightUpperLeg", "RightLowerLeg" },
	{ "RightLowerLeg", "RightFoot" },
}

local function newEntry()
	return {
		box = Draw.square({ Thickness = 1, Filled = false, Color = color, Transparency = 1, Visible = false }),
		name = Draw.text({
			Size = 14,
			Center = true,
			Outline = true,
			Color = Color3.new(1, 1, 1),
			Transparency = 1,
			Visible = false,
		}),
		healthBack = Draw.square({ Thickness = 1, Filled = true, Color = Color3.new(0, 0, 0), Transparency = 0.6, Visible = false }),
		healthFill = Draw.square({ Thickness = 0, Filled = true, Color = Color3.fromRGB(80, 220, 120), Transparency = 0.15, Visible = false }),
		distance = Draw.text({
			Size = 12,
			Center = true,
			Outline = true,
			Color = Color3.fromRGB(215, 215, 225),
			Transparency = 1,
			Visible = false,
		}),
		tracer = Draw.line({ Thickness = 1, Color = color, Transparency = 1, Visible = false }),
		skeleton = {},
	}
end

local function hideEntry(entry)
	Draw.set(entry.box, { Visible = false })
	Draw.set(entry.name, { Visible = false })
	Draw.set(entry.healthBack, { Visible = false })
	Draw.set(entry.healthFill, { Visible = false })
	Draw.set(entry.distance, { Visible = false })
	Draw.set(entry.tracer, { Visible = false })
	for _, line in ipairs(entry.skeleton) do
		Draw.set(line, { Visible = false })
	end
end

local function removeEntry(player)
	local entry = entries[player]
	if not entry then
		return
	end
	hideEntry(entry)
	Draw.remove(entry.box)
	Draw.remove(entry.name)
	Draw.remove(entry.healthBack)
	Draw.remove(entry.healthFill)
	Draw.remove(entry.distance)
	Draw.remove(entry.tracer)
	for _, line in ipairs(entry.skeleton) do
		Draw.remove(line)
	end
	entries[player] = nil
end

local function ensureEntry(player)
	local entry = entries[player]
	if entry then
		return entry
	end
	entry = newEntry()
	entries[player] = entry
	return entry
end

local function drawSkeleton(entry, character)
	for index, pair in ipairs(SKELETON) do
		local line = entry.skeleton[index]
		if not line then
			line = Draw.line({ Thickness = 1, Color = color, Transparency = 1 })
			entry.skeleton[index] = line
		end
		if not line then
			return
		end

		local a = character:FindFirstChild(pair[1])
		local b = character:FindFirstChild(pair[2])
		if a and b then
			local from, fromOn = Targeting.project(a.Position)
			local to, toOn = Targeting.project(b.Position)
			if from and to and fromOn and toOn then
				Draw.set(line, { From = from, To = to, Visible = true, Color = color })
			else
				Draw.set(line, { Visible = false })
			end
		else
			Draw.set(line, { Visible = false })
		end
	end
end

local function updateEntry(entry, data)
	local character = data.character
	local head = character:FindFirstChild("Head") or data.root
	local root = data.root

	local top = head.Position + Vector3.new(0, head.Size.Y * 0.5 + 0.4, 0)
	local bottom = root.Position - Vector3.new(0, 2.6, 0)

	local topScreen, topOn = Targeting.project(top)
	local bottomScreen, bottomOn = Targeting.project(bottom)

	if not topScreen or not bottomScreen or not topOn or not bottomOn then
		hideEntry(entry)
		return
	end

	local height = math.abs(bottomScreen.Y - topScreen.Y)
	if height < 6 then
		hideEntry(entry)
		return
	end
	local width = height * 0.55
	local centerX = topScreen.X

	local viewport = Targeting.viewport()

	if Config.get("ESPBox") then
		Draw.set(entry.box, {
			Position = Vector2.new(centerX - width * 0.5, topScreen.Y),
			Size = Vector2.new(width, height),
			Color = color,
			Visible = true,
		})
	else
		Draw.set(entry.box, { Visible = false })
	end

	if Config.get("ESPName") then
		Draw.set(entry.name, {
			Position = Vector2.new(centerX, topScreen.Y - 16),
			Text = data.player.Name,
			Visible = true,
		})
	else
		Draw.set(entry.name, { Visible = false })
	end

	if Config.get("ESPDistance") then
		Draw.set(entry.distance, {
			Position = Vector2.new(centerX, bottomScreen.Y + 4),
			Text = ("%d studs"):format(math.floor(data.distance)),
			Visible = true,
		})
	else
		Draw.set(entry.distance, { Visible = false })
	end

	if Config.get("ESPHealth") then
		local health = data.humanoid.Health
		local maxHealth = math.max(data.humanoid.MaxHealth, 1)
		local ratio = math.clamp(health / maxHealth, 0, 1)
		local barX = centerX - width * 0.5 - 6
		local barHeight = height * ratio

		Draw.set(entry.healthBack, {
			Position = Vector2.new(barX, topScreen.Y),
			Size = Vector2.new(3, height),
			Visible = true,
		})
		Draw.set(entry.healthFill, {
			Position = Vector2.new(barX, bottomScreen.Y - barHeight),
			Size = Vector2.new(3, barHeight),
			Color = Color3.fromRGB(80 + 175 * (1 - ratio), 220 * ratio, 70),
			Visible = true,
		})
	else
		Draw.set(entry.healthBack, { Visible = false })
		Draw.set(entry.healthFill, { Visible = false })
	end

	if Config.get("ESPTracer") then
		Draw.set(entry.tracer, {
			From = Vector2.new(viewport.X * 0.5, viewport.Y),
			To = Vector2.new(centerX, bottomScreen.Y),
			Color = color,
			Visible = true,
		})
	else
		Draw.set(entry.tracer, { Visible = false })
	end

	if Config.get("ESPSkeleton") then
		drawSkeleton(entry, character)
	else
		for _, line in ipairs(entry.skeleton) do
			Draw.set(line, { Visible = false })
		end
	end
end

local function updateFovCircle()
	if not fovCircle then
		fovCircle = Draw.circle({ Thickness = 1, Filled = false, Color = color, Transparency = 0.5 })
	end
	if not fovCircle then
		return
	end

	if Config.get("AimFOVCircle") and Config.get("Aim") then
		local viewport = Targeting.viewport()
		Draw.set(fovCircle, {
			Position = viewport * 0.5,
			Radius = Config.get("AimFOV"),
			Visible = true,
		})
	else
		Draw.set(fovCircle, { Visible = false })
	end
end

local function tick()
	if not enabled then
		return
	end

	local seen = {}
	for _, data in ipairs(Targeting.candidates({
		teamCheck = Config.get("ESPTeamCheck"),
		maxDistance = Config.get("ESPMaxDistance"),
	})) do
		seen[data.player] = true
		local entry = ensureEntry(data.player)
		updateEntry(entry, data)
	end

	for player in pairs(entries) do
		if not seen[player] then
			hideEntry(entries[player])
		end
	end

	updateFovCircle()
end

function Visuals.setEnabled(state)
	enabled = state

	if not state then
		if connection then
			connection:Disconnect()
			connection = nil
		end
		for player in pairs(entries) do
			removeEntry(player)
		end
		if fovCircle then
			Draw.remove(fovCircle)
			fovCircle = nil
		end
		return true
	end

	if not Draw.available() then
		return false, "executor has no Drawing API"
	end

	if not connection then
		connection = RunService.RenderStepped:Connect(tick)
	end
	return true
end

function Visuals.setColor(value)
	color = value
	for _, entry in pairs(entries) do
		Draw.set(entry.box, { Color = value })
		Draw.set(entry.tracer, { Color = value })
		Draw.set(entry.skeleton[1], { Color = value })
	end
	if fovCircle then
		Draw.set(fovCircle, { Color = value })
	end
	return true
end

function Visuals.bind()
	Players.PlayerRemoving:Connect(function(player)
		removeEntry(player)
	end)
end

function Visuals.destroy()
	Visuals.setEnabled(false)
	if connection then
		connection:Disconnect()
		connection = nil
	end
end

return Visuals
end
__modules["features/world"] = function()
local Lighting = game:GetService("Lighting")
local Workspace = game:GetService("Workspace")

local Config = __require("config")

local World = {}

local snapshot

function World.capture()
	if snapshot then
		return
	end
	snapshot = {
		ClockTime = Lighting.ClockTime,
		Brightness = Lighting.Brightness,
		FogEnd = Lighting.FogEnd,
		FogStart = Lighting.FogStart,
		Gravity = Workspace.Gravity,
		Ambient = Lighting.Ambient,
		FogColor = Lighting.FogColor,
		Exposure = Lighting.ExposureCompensation,
	}
end

function World.apply()
	World.capture()
	Lighting.ClockTime = Config.get("ClockTime")
	Lighting.Brightness = Config.get("Brightness")
	Lighting.FogEnd = Config.get("WorldFogEnd")
	Lighting.ExposureCompensation = Config.get("Exposure")
	Workspace.Gravity = Config.get("Gravity")
	return true
end

function World.setAmbient(color)
	World.capture()
	Lighting.Ambient = color
	Lighting.OutdoorAmbient = color
	return true
end

function World.setFogColor(color)
	World.capture()
	Lighting.FogColor = color
	return true
end

function World.reset()
	if not snapshot then
		return true
	end
	Lighting.ClockTime = snapshot.ClockTime
	Lighting.Brightness = snapshot.Brightness
	Lighting.FogEnd = snapshot.FogEnd
	Lighting.FogStart = snapshot.FogStart
	Lighting.Ambient = snapshot.Ambient
	Lighting.FogColor = snapshot.FogColor
	Lighting.ExposureCompensation = snapshot.Exposure
	Workspace.Gravity = snapshot.Gravity
	snapshot = nil
	return true
end

function World.destroy()
	World.reset()
end

return World
end
__modules["features/hud"] = function()
local Players = game:GetService("Players")
local RunService = game:GetService("RunService")
local Stats = game:GetService("Stats")

local Config = __require("config")
local Draw = __require("features/draw")

local HUD = {}

local ORDER = { "FPS", "Ping", "Players", "Coords", "Clock" }
local lines = {}
local connection
local enabled = false
local frames, elapsed, fps = 0, 0, 0
local color = Color3.fromRGB(235, 235, 242)

local function lineFor(key)
	if lines[key] then
		return lines[key]
	end
	local index = table.find(ORDER, key) or 1
	lines[key] = Draw.text({
		Size = 13,
		Color = color,
		Outline = true,
		Visible = false,
		Position = Vector2.new(12, 12 + (index - 1) * 16),
	})
	return lines[key]
end

local function ping()
	local ok, value = pcall(function()
		return Stats.Network.ServerStatsItem["Data Ping"]:GetValue()
	end)
	if ok and type(value) == "number" then
		return math.floor(value)
	end
	return nil
end

local function refresh()
	fps = (elapsed > 0) and math.floor(frames / elapsed + 0.5) or fps
	frames, elapsed = 0, 0

	local values = {
		FPS = ("fps: %d"):format(fps),
		Ping = (function()
			local value = ping()
			return value and ("ping: %d ms"):format(value) or "ping: ?"
		end)(),
		Players = ("players: %d"):format(#Players:GetPlayers()),
		Clock = ("time: %s"):format(os.date("%H:%M:%S")),
	}

	local character = Players.LocalPlayer and Players.LocalPlayer.Character
	local root = character and character:FindFirstChild("HumanoidRootPart")
	values.Coords = root
		and ("pos: %d, %d, %d"):format(math.floor(root.Position.X), math.floor(root.Position.Y), math.floor(root.Position.Z))
		or "pos: ?"

	for key, text in pairs(values) do
		local line = lineFor(key)
		if line then
			local shown = enabled and Config.get("HUD_" .. key)
			Draw.set(line, { Visible = shown == true, Text = text })
		end
	end
end

function HUD.setEnabled(state)
	enabled = state

	if not state then
		if connection then
			connection:Disconnect()
			connection = nil
		end
		for _, line in pairs(lines) do
			Draw.set(line, { Visible = false })
		end
		return true
	end

	if not Draw.available() then
		return false, "executor has no Drawing API"
	end

	if not connection then
		connection = RunService.Heartbeat:Connect(function(delta)
			frames += 1
			elapsed += delta
			if elapsed >= 0.25 then
				refresh()
			end
		end)
	end
	refresh()
	return true
end

function HUD.setColor(value)
	color = value
	for _, line in pairs(lines) do
		Draw.set(line, { Color = value })
	end
end

function HUD.destroy()
	HUD.setEnabled(false)
	for key, line in pairs(lines) do
		Draw.remove(line)
		lines[key] = nil
	end
end

return HUD
end
__modules["features/crosshair"] = function()
local RunService = game:GetService("RunService")
local Workspace = game:GetService("Workspace")

local Config = __require("config")
local Draw = __require("features/draw")

local Crosshair = {}

local arms = {}
local dot
local connection
local enabled = false
local color = Color3.fromRGB(255, 255, 255)

local function ensure()
	if #arms == 0 then
		for index = 1, 4 do
			arms[index] = Draw.line({ Thickness = 1, Color = color, Transparency = 0.1, Visible = false })
		end
	end
	if not dot then
		dot = Draw.square({ Thickness = 0, Filled = true, Color = color, Transparency = 0.1, Visible = false })
	end
end

local function viewport()
	local camera = Workspace.CurrentCamera
	if camera then
		return camera.ViewportSize
	end
	return Vector2.new(1920, 1080)
end

local function draw()
	if not enabled then
		return
	end
	ensure()
	if not arms[1] then
		return
	end

	local center = viewport() * 0.5
	local size = Config.get("CrosshairSize")
	local gap = Config.get("CrosshairGap")
	local thickness = Config.get("CrosshairThickness")

	Draw.set(arms[1], { From = Vector2.new(center.X, center.Y - gap), To = Vector2.new(center.X, center.Y - gap - size) })
	Draw.set(arms[2], { From = Vector2.new(center.X, center.Y + gap), To = Vector2.new(center.X, center.Y + gap + size) })
	Draw.set(arms[3], { From = Vector2.new(center.X - gap, center.Y), To = Vector2.new(center.X - gap - size, center.Y) })
	Draw.set(arms[4], { From = Vector2.new(center.X + gap, center.Y), To = Vector2.new(center.X + gap + size, center.Y) })

	for index = 1, 4 do
		Draw.set(arms[index], { Visible = true, Color = color, Thickness = thickness })
	end

	if Config.get("CrosshairDot") then
		Draw.set(dot, {
			Position = center - Vector2.new(1, 1),
			Size = Vector2.new(2, 2),
			Visible = true,
			Color = color,
		})
	else
		Draw.set(dot, { Visible = false })
	end
end

function Crosshair.setEnabled(state)
	enabled = state

	if not state then
		if connection then
			connection:Disconnect()
			connection = nil
		end
		for _, arm in ipairs(arms) do
			Draw.set(arm, { Visible = false })
		end
		Draw.set(dot, { Visible = false })
		return true
	end

	if not Draw.available() then
		return false, "executor has no Drawing API"
	end

	ensure()
	if not connection then
		connection = RunService.RenderStepped:Connect(draw)
	end
	draw()
	return true
end

function Crosshair.setColor(value)
	color = value
	for _, arm in ipairs(arms) do
		Draw.set(arm, { Color = value })
	end
	Draw.set(dot, { Color = value })
end

function Crosshair.destroy()
	Crosshair.setEnabled(false)
	for index, arm in ipairs(arms) do
		Draw.remove(arm)
		arms[index] = nil
	end
	Draw.remove(dot)
	dot = nil
end

return Crosshair
end
__modules["features/hitbox"] = function()
local Players = game:GetService("Players")
local RunService = game:GetService("RunService")

local Config = __require("config")

local Hitbox = {}

local originals = {}
local connection
local enabled = false
local accumulator = 0

local function apply(player)
	if player == Players.LocalPlayer then
		return
	end
	local character = player.Character
	local head = character and character:FindFirstChild("Head")
	if not head or not head:IsA("BasePart") then
		return
	end

	local base = originals[head]
	if not base then
		base = head.Size
		originals[head] = base
	end

	local scale = Config.get("HitboxScale")
	head.Size = Vector3.new(base.X * scale, base.Y * scale, base.Z * scale)
	head.CanCollide = false
end

local function restore()
	for part, size in pairs(originals) do
		if part.Parent then
			part.Size = size
		end
	end
	table.clear(originals)
end

function Hitbox.setEnabled(state)
	enabled = state

	if not state then
		if connection then
			connection:Disconnect()
			connection = nil
		end
		restore()
		return true
	end

	if not connection then
		connection = RunService.Heartbeat:Connect(function(delta)
			if not enabled then
				return
			end
			accumulator += delta
			if accumulator < 0.5 then
				return
			end
			accumulator = 0
			for _, player in ipairs(Players:GetPlayers()) do
				apply(player)
			end
		end)
	end
	return true
end

function Hitbox.destroy()
	Hitbox.setEnabled(false)
end

return Hitbox
end
__modules["features/aim"] = function()
local RunService = game:GetService("RunService")
local UserInputService = game:GetService("UserInputService")
local Workspace = game:GetService("Workspace")

local Config = __require("config")
local Targeting = __require("features/targeting")

local Aim = {}

local connection
local enabled = false

local function isKeyDown()
	local key = Config.get("AimKey") or "MB2"
	if key == "MB1" then
		return UserInputService:IsMouseButtonPressed(Enum.UserInputType.MouseButton1)
	elseif key == "MB2" then
		return UserInputService:IsMouseButtonPressed(Enum.UserInputType.MouseButton2)
	elseif key == "Always" then
		return true
	end
	local keyCode = Enum.KeyCode[key]
	if keyCode then
		return UserInputService:IsKeyDown(keyCode)
	end
	return false
end

local function targetPosition(entry)
	local part = Targeting.part(entry, Config.get("AimPart") or "Head")
	if not part then
		return nil
	end
	local position = part.Position

	if Config.get("AimPrediction") then
		local root = entry.root
		local lead = Config.get("AimPredictionAmount") or 0.12
		position = position + root.AssemblyLinearVelocity * lead
	end

	return position + Vector3.new(0, Config.get("AimOffsetY") or 0, 0)
end

local function step()
	if not enabled or not isKeyDown() then
		return
	end

	local camera = Workspace.CurrentCamera
	if not camera then
		return
	end

	local entry = Targeting.closestToScreen({
		fov = Config.get("AimFOV"),
		part = Config.get("AimPart"),
		teamCheck = Config.get("AimTeamCheck"),
		maxDistance = Config.get("AimMaxDistance"),
		priority = Config.get("AimPriority"),
	})
	if not entry then
		return
	end

	if Config.get("AimVisibleOnly") and not Targeting.visible(entry) then
		return
	end

	local position = targetPosition(entry)
	if not position then
		return
	end

	local speed = math.clamp(tonumber(Config.get("AimSmooth")) or 0.35, 0.01, 1)
	local alpha = 1 - speed

	local goal = CFrame.lookAt(camera.CFrame.Position, position)
	camera.CFrame = camera.CFrame:Lerp(goal, alpha)
end

function Aim.setEnabled(state)
	enabled = state
	if not state then
		if connection then
			connection:Disconnect()
			connection = nil
		end
		return true
	end
	if not connection then
		connection = RunService.RenderStepped:Connect(step)
	end
	return true
end

function Aim.destroy()
	enabled = false
	if connection then
		connection:Disconnect()
		connection = nil
	end
end

return Aim
end
__modules["features/weapon"] = function()
local RunService = game:GetService("RunService")
local Workspace = game:GetService("Workspace")

local Config = __require("config")

local Weapon = {}

local connection
local enabled = false
local lastPitch
local lockedFov

local function pitchOf(cframe)
	local look = cframe.LookVector
	return math.asin(math.clamp(look.Y, -1, 1))
end

local function step()
	if not enabled then
		return
	end

	local camera = Workspace.CurrentCamera
	if not camera then
		return
	end

	local cframe = camera.CFrame

	if Config.get("NoRecoil") then
		local pitch = pitchOf(cframe)
		if lastPitch and pitch > lastPitch then
			local strength = math.clamp(Config.get("RecoilStrength") or 1, 0, 1)
			local targetPitch = lastPitch + (pitch - lastPitch) * (1 - strength)
			local flat = Vector3.new(cframe.LookVector.X, 0, cframe.LookVector.Z)
			if flat.Magnitude > 1e-3 then
				flat = flat.Unit
				local horizontal = math.sqrt(math.max(0, 1 - targetPitch * targetPitch))
				local look = Vector3.new(flat.X * horizontal, targetPitch, flat.Z * horizontal)
				camera.CFrame = CFrame.lookAt(cframe.Position, cframe.Position + look)
			end
		end
		lastPitch = pitchOf(camera.CFrame)
	else
		lastPitch = nil
	end

	if Config.get("NoSway") then
		local current = camera.CFrame
		local right = current.RightVector
		local flatRight = Vector3.new(right.X, 0, right.Z)
		if flatRight.Magnitude > 1e-3 then
			local up = Vector3.new(0, 1, 0)
			camera.CFrame = CFrame.fromMatrix(current.Position, flatRight.Unit, up)
		end
	end

	if Config.get("NoSpread") then
		if not lockedFov then
			lockedFov = camera.FieldOfView
		end
		if math.abs(camera.FieldOfView - lockedFov) > 0.01 then
			camera.FieldOfView = lockedFov
		end
	else
		lockedFov = nil
	end
end

function Weapon.setEnabled(state)
	enabled = state
	if not state then
		if connection then
			connection:Disconnect()
			connection = nil
		end
		lastPitch = nil
		lockedFov = nil
		return true
	end
	if not connection then
		connection = RunService.RenderStepped:Connect(step)
	end
	return true
end

function Weapon.destroy()
	Weapon.setEnabled(false)
end

return Weapon
end
__modules["features/triggerbot"] = function()
local RunService = game:GetService("RunService")
local UserInputService = game:GetService("UserInputService")
local VirtualUser = game:GetService("VirtualUser")

local Config = __require("config")
local Targeting = __require("features/targeting")

local Triggerbot = {}

local connection
local enabled = false
local lastShot = 0

local function keyHeld()
	local key = Config.get("TriggerKey") or "MB2"
	if key == "MB1" then
		return UserInputService:IsMouseButtonPressed(Enum.UserInputType.MouseButton1)
	elseif key == "MB2" then
		return UserInputService:IsMouseButtonPressed(Enum.UserInputType.MouseButton2)
	elseif key == "Always" then
		return true
	end
	local keyCode = Enum.KeyCode[key]
	if keyCode then
		return UserInputService:IsKeyDown(keyCode)
	end
	return false
end

local function click()
	local ok = pcall(function()
		mouse1click()
	end)
	if ok then
		return true
	end
	local fallback = pcall(function()
		VirtualUser:CaptureController()
		VirtualUser:ClickButton1(Vector2.new())
	end)
	return fallback
end

local function underCrosshair()
	local viewport = Targeting.viewport()
	local center = viewport * 0.5
	local fov = Config.get("TriggerFOV") or 4

	for _, entry in ipairs(Targeting.candidates({
		teamCheck = Config.get("TriggerTeamCheck"),
		maxDistance = Config.get("TriggerMaxDistance"),
	})) do
		local parts = { entry.character:FindFirstChild("Head"), entry.root }
		for _, part in ipairs(parts) do
			if part then
				local screen, onScreen = Targeting.project(part.Position)
				if screen and onScreen and (screen - center).Magnitude <= fov then
					if Config.get("TriggerVisibleOnly") and not Targeting.visible(entry) then
						continue
					end
					return entry
				end
			end
		end
	end
	return nil
end

local function step()
	if not enabled or not keyHeld() then
		return
	end

	local now = os.clock()
	if now - lastShot < (Config.get("TriggerDelay") or 0.05) then
		return
	end

	if underCrosshair() then
		lastShot = now
		click()
	end
end

function Triggerbot.setEnabled(state)
	enabled = state
	if not state then
		if connection then
			connection:Disconnect()
			connection = nil
		end
		return true
	end
	if not connection then
		connection = RunService.RenderStepped:Connect(step)
	end
	return true
end

function Triggerbot.destroy()
	Triggerbot.setEnabled(false)
end

return Triggerbot
end
__modules["features/silent"] = function()
local Players = game:GetService("Players")
local Config = __require("config")
local Targeting = __require("features/targeting")

local Silent = {}

local enabled = false
local mouseMetatable
local originalIndex

local function targetEntry()
	return Targeting.closestToScreen({
		fov = Config.get("SilentFOV"),
		part = "Head",
		teamCheck = Config.get("SilentTeamCheck"),
		maxDistance = Config.get("AimMaxDistance"),
	})
end

function Silent.setEnabled(state)
	enabled = state

	if not state then
		if mouseMetatable and originalIndex ~= nil then
			mouseMetatable.__index = originalIndex
			mouseMetatable = nil
			originalIndex = nil
		end
		return true
	end

	if mouseMetatable then
		return true
	end

	if type(getrawmetatable) ~= "function" then
		return false, "executor has no getrawmetatable"
	end

	local player = Players.LocalPlayer
	if not player then
		return false, "no local player"
	end

	local ok, mouse = pcall(function()
		return player:GetMouse()
	end)
	if not ok or not mouse then
		return false, "no mouse object"
	end

	local metatableOk, metatable = pcall(getrawmetatable, mouse)
	if not metatableOk or type(metatable) ~= "table" then
		return false, "mouse metatable is protected"
	end

	originalIndex = metatable.__index
	mouseMetatable = metatable

	metatable.__index = function(self, key)
		if enabled and (key == "Hit" or key == "Target") then
			local entry = targetEntry()
			if entry then
				local part = entry.character:FindFirstChild("Head") or entry.root
				if part then
					if key == "Hit" then
						return CFrame.new(part.Position)
					end
					return part
				end
			end
		end

		if type(originalIndex) == "function" then
			return originalIndex(self, key)
		end
		return originalIndex
	end

	return true
end

function Silent.destroy()
	Silent.setEnabled(false)
end

return Silent
end
__modules["features/hitsound"] = function()
local Players = game:GetService("Players")
local RunService = game:GetService("RunService")
local SoundService = game:GetService("SoundService")

local Config = __require("config")

local Hitsound = {}

Hitsound.choices = {
	{ name = "Ping", id = "rbxasset://sounds/electronicpingshort.wav" },
	{ name = "Button", id = "rbxasset://sounds/button.wav" },
	{ name = "Switch", id = "rbxasset://sounds/switch3.wav" },
	{ name = "Click", id = "rbxasset://sounds/clickfast.wav" },
	{ name = "Hit", id = "rbxasset://sounds/hit.wav" },
	{ name = "Impact", id = "rbxasset://sounds/impact_generic.mp3" },
	{ name = "Water", id = "rbxasset://sounds/impact_water.mp3" },
	{ name = "Bass", id = "rbxasset://sounds/bass.wav" },
}

local connection
local enabled = false
local health = {}

local function resolveSound()
	local custom = Config.get("HitSoundCustom") or ""
	if type(custom) == "string" and custom ~= "" then
		if custom:match("^%d+$") then
			return "rbxassetid://" .. custom
		end
		return custom
	end

	local choice = Config.get("HitSoundChoice") or "Ping"
	for _, entry in ipairs(Hitsound.choices) do
		if entry.name == choice then
			return entry.id
		end
	end
	return Hitsound.choices[1].id
end

function Hitsound.play()
	local id = resolveSound()
	local sound = Instance.new("Sound")
	sound.SoundId = id
	sound.Volume = Config.get("HitSoundVolume") or 1
	sound.PlaybackSpeed = Config.get("HitSoundPitch") or 1
	sound.Parent = SoundService

	SoundService:PlayLocalSound(sound)
	task.delay(4, function()
		sound:Destroy()
	end)
end

local function scan()
	for _, player in ipairs(Players:GetPlayers()) do
		local humanoid = player.Character and player.Character:FindFirstChildOfClass("Humanoid")
		if humanoid then
			local previous = health[player]
			if previous and humanoid.Health < previous - 0.5 and humanoid.Health > 0 then
				Hitsound.play()
			end
			health[player] = humanoid.Health
		else
			health[player] = nil
		end
	end
end

function Hitsound.setEnabled(state)
	enabled = state

	if not state then
		if connection then
			connection:Disconnect()
			connection = nil
		end
		table.clear(health)
		return true
	end

	if not connection then
		local accumulator = 0
		connection = RunService.Heartbeat:Connect(function(delta)
			if not enabled then
				return
			end
			accumulator += delta
			if accumulator < 0.1 then
				return
			end
			accumulator = 0
			scan()
		end)
	end
	return true
end

function Hitsound.destroy()
	Hitsound.setEnabled(false)
end

return Hitsound
end
